@startuml

enum LevelOfTutoring {
  PrimarySchool
  HighSchool
  University
}

enum SessionStatus {
  Proposed
  Confirmed
  Completed
  Paid
  Cancelled
}

enum PaymentKind {
  CreditCard
  WireTransfer
}

class User {
  + name : string
  + email : string
}

class Tutor extends User {
  + bankAccount : string
}

class Student extends User {}

class Subject {
  + name : string
}

class TutoringOffer {
  + hourlyPrice : float
}

class TutoringRequest {
  + tutoringLevel : LevelOfTutoring
  + targetDate : date
  + targetTime : time
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
  + sessionStatus : SessionStatus
}

class TutorAvailability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class Payment {
  + paymentForm : PaymentKind
  + amount : float
  + paymentDate : date
}

class BestTutorAward {
  + month : int
  + year : int
}

Tutor "1" *-- "*" TutoringOffer
Tutor "1" *-- "*" TutorAvailability
Tutor "1" -- "*" TutoringRequest
Tutor "1" -- "*" TutoringSession
Student "1" -- "*" TutoringRequest
Student "1" -- "*" TutoringSession
Student "1" -- "0..1" Payment
TutoringRequest "1" -- "0..1" TutoringSession
TutoringSession "1" -- "0..1" Payment
Subject "1" -- "*" TutoringOffer
Subject "1" -- "*" TutoringRequest
Tutor "1" -- "*" BestTutorAward

@enduml

